mapper.select:


    inner join sys_user u on u.user_name = equipment.create_by and u.status = '0'
    inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'


    equipment.del_flag = '0'
     and equipment.name like concat('%', #{name}, '%')
     and equipment.equ_no = #{equNo}
     and equipment.asset_no = #{assetNo}
     and equipment.serial_no = #{serialNo}
     and equipment.model = #{model}
     and equipment.function_location = #{functionLocation}
     and equipment.dep_id = #{depId}
     and equipment.dep_name like concat('%', #{depName}, '%')
     and equipment.supplier = #{supplier}
     and equipment.use_status = #{useStatus}
     and equipment.person = #{person}


${params.dataScope}
ORDER BY create_time DESC
